/* @lc app=leetcode id=2035 lang=kotlin */ class Solution { fun sub(a: List<Int>): Map<Int, List<Int>> = (0 until (1 shl a.size)).groupBy({ Integer.bitCount(it) }, { m -> a.indices.filter { m shr it and 1 == 1 }.sumOf { a[it] } }).mapValues { it.value.sorted() } fun minimumDifference(nums: IntArray): Int = (nums.size / 2).let { n -> nums.sum().let { tot -> sub(nums.take(n)).let { l -> sub(nums.drop(n)).let { r -> l.entries.minOf { (k, ls) -> ls.minOf { s -> r[n - k]!!.let { rs -> (tot - 2 * s).let { t -> rs.binarySearch(Math.floorDiv(t, 2)).let { if (it >= 0) it else -it - 1 }.let { ins -> listOfNotNull(rs.getOrNull(ins), rs.getOrNull(ins - 1)).minOf { x -> Math.abs(t - 2 * x) } } } } } } } } } } }